changeSet.sql:
create or alter procedure dbo.UpsertCompanyFeatureFlag
	@companyId int,
	@slug varchar(100),
	@value bit
as
begin
	set nocount on;

	declare @flagId smallint;
	select @flagId = Id from FeatureFlag where Slug = @slug;

	if @flagId is not null
	begin
		if exists (select 1 from CompanyFeatureFlag where CompanyID = @companyID and FeatureFlagId = @flagId)
		begin
			update CompanyFeatureFlag set [Value] = @value where CompanyID = @companyId and FeatureFlagId = @flagId;
		end
		else
		begin 
			insert into CompanyFeatureFlag (CompanyId, FeatureFlagId, [Value]) values (@companyId, @flagId, @value);
		end
	end

	exec ReadFeatureFlagsForCompany	@companyId;
end
